    uint8 constant KEEP_ARGS = 1 << 3;
}

library GatewayOP {
    uint8 constant PUSH_0 = 0;
    uint8 constant PUSH_1 = 1;
    uint8 constant PUSH_2 = 2;
    uint8 constant PUSH_3 = 3;
    uint8 constant PUSH_4 = 4;
