    uint8 constant GET_SLOT = 33;
    uint8 constant GET_TARGET = 34;
    uint8 constant STACK_SIZE = 35;
	uint8 constant IS_CONTRACT = 36;

    uint8 constant PUSH_BYTES = 40;
    uint8 constant PUSH_STACK = 41;
